with w as(select*from public.works where open_library_id in('OL15171136W','OL733285W','OL134887W','OL134889W','OL2412102W','OL26416675W','OL5714309W','OL20760166W','OL23658202W','OL42402317W','OL24347979W','OL85351W','OL21370801W','OL15959994W','OL1966510W','OL36775731W','OL28095854W','OL27591348W','OL19624297W','OL20908682W','OL34612213W','OL20168296W','OL20011828W','OL17455355W','OL2412107W','OL37618590W','OL17334061W','OL37617445W','OL20649783W','OL37247638W','OL2412076W','OL41249W','OL17792692W','OL17410022W','OL37618227W','OL37585489W','OL19359456W','OL79331W','OL43548572W','OL85747W','OL37574587W','OL37827517W','OL16806999W','OL37617228W','OL20151084W','OL42457696W','OL44584989W','OL14963222W','OL554727W','OL85744W','OL4772459W','OL2463551W','OL554726W','OL17902867W','OL24212743W','OL1998799W','OL15638721W','OL20887200W','OL15171940W','OL462950W','OL42399188W')) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','works',(select jsonb_agg(to_jsonb(w)order by id)from w),'editions',(select jsonb_agg(to_jsonb(e)order by id)from public.editions e where work_id in(select id from w)),'authors',(select jsonb_agg(to_jsonb(a)order by id)from public.authors a where id in(select author_id from w)))as readback;